diff --git a/libgps_sock.c b/libgps_sock.c
index 74619c16d..a86efb5e7 100644
--- a/libgps_sock.c
+++ b/libgps_sock.c
@@ -129,18 +129,21 @@ int gps_sock_open(const char *host, const char *port,
     return 0;
 }

-bool gps_sock_waiting(const struct gps_data_t *gpsdata, int timeout)
 /* is there input waiting from the GPS? */
-/* timeout is in uSec */
+/* timeout is in milli Seconds */
+bool gps_sock_waiting(const struct gps_data_t *gpsdata, int timeout)
 {
 #ifndef USE_QT
+    struct timespec to;
+
     libgps_debug_trace((DEBUG_CALLS, "gps_waiting(%d): %d\n",
                        timeout, PRIVATE(gpsdata)->waitcount++));
     if (PRIVATE(gpsdata)->waiting > 0)
 	return true;

+    MSTOTS(&to, timeout);
     /* all error conditions return "not waiting" -- crude but effective */
-    return nanowait(gpsdata->gps_fd, timeout * 1000);
+    return nanowait(gpsdata->gps_fd, &to);
 #else
     return ((QTcpSocket *) (gpsdata->gps_fd))->waitForReadyRead(timeout / 1000);
 #endif

diff --git a/driver_geostar.c b/driver_geostar.c
index a011fda22..ff6b3eccf 100644
--- a/driver_geostar.c
+++ b/driver_geostar.c
@@ -12,13 +12,13 @@

 #include "gpsd_config.h"  /* must be before all includes */

+#include <math.h>
 #include <stdbool.h>
 #include <stdio.h>
-#include <math.h>
 #include <string.h>

-#include "gpsd.h"
 #include "bits.h"
+#include "gpsd.h"
 #include "strfuncs.h"
 #include "timespec.h"

@@ -93,8 +93,13 @@ static bool geostar_detect(struct gps_device_t *session)
     putbe32(buf, 0, 0);
     if (geostar_write(session, 0xc1, buf, 1) == 0) {
 	unsigned int n;
+        struct timespec to;
+        // FIXME: this holds the main loop from running...
 	for (n = 0; n < 3; n++) {
-	    if (!nanowait(myfd, NS_IN_SEC))
+            // wait one second
+            to.tv_sec = 1;
+            to.tv_nsec = 0;
+	    if (!nanowait(myfd, &to))
 		break;
 	    if (generic_get(session) >= 0) {
 		if (session->lexer.type == GEOSTAR_PACKET) {
@@ -629,3 +634,5 @@ const struct gps_type_t driver_geostar =
 /* *INDENT-ON* */

 #endif /* GEOSTAR_ENABLE */
+
